CREATE OR REPLACE SEMANTIC VIEW "CHAR_DB"."CHAR_SCHEMA"."COMPETITIVE_MARKETING_ANALYSIS_MORE_SYNONYMS_1_SEMANTIC"
TABLES (
  CATEGORY AS "CHAR_DB"."CHAR_SCHEMA"."CATEGORY" PRIMARY KEY ("CATEGORY"),
  COL_DATE AS "CHAR_DB"."CHAR_SCHEMA"."DATE" PRIMARY KEY ("COL_DATE"),
  GEO AS "CHAR_DB"."CHAR_SCHEMA"."GEO" PRIMARY KEY ("ZIP"),
  INDICATORS AS "CHAR_DB"."CHAR_SCHEMA"."INDICATORS",
  KPI AS "CHAR_DB"."CHAR_SCHEMA"."KPI",
  MANUFACTURER AS "CHAR_DB"."CHAR_SCHEMA"."MANUFACTURER" PRIMARY KEY ("MANUFACTURERID"),
  PRODUCT AS "CHAR_DB"."CHAR_SCHEMA"."PRODUCT" PRIMARY KEY ("PRODUCTID"),
  SALESFACT AS "CHAR_DB"."CHAR_SCHEMA"."SALESFACT_ENRICHED",
  SENTIMENT AS "CHAR_DB"."CHAR_SCHEMA"."SENTIMENT"
)
RELATIONSHIPS (
  PRODUCT_MANUFACTURERID_MANUFACTURER_MANUFACTURERID AS PRODUCT ("MANUFACTURERID") REFERENCES MANUFACTURER ("MANUFACTURERID"),
  SALESFACT_PRODUCTID_PRODUCT_PRODUCTID AS SALESFACT ("PRODUCTID") REFERENCES PRODUCT ("PRODUCTID"),
  SALESFACT_DATE_DATE_DATE AS SALESFACT ("COL_DATE") REFERENCES COL_DATE ("COL_DATE"),
  SALESFACT_ZIP_GEO_ZIP AS SALESFACT ("ZIP") REFERENCES GEO ("ZIP"),
  SENTIMENT_ZIP_GEO_ZIP AS SENTIMENT ("ZIP") REFERENCES GEO ("ZIP"),
  SENTIMENT_DATE_DATE_DATE AS SENTIMENT ("COL_DATE") REFERENCES COL_DATE ("COL_DATE"),
  SENTIMENT_MANUFACTURERID_MANUFACTURER_MANUFACTURERID AS SENTIMENT ("MANUFACTURERID") REFERENCES MANUFACTURER ("MANUFACTURERID"),
  PRODUCT_SEGMENT_CATEGORY_CATEGORY AS PRODUCT ("SEGMENT") REFERENCES CATEGORY ("CATEGORY")
)
FACTS (
  PRIVATE SALESFACT."UNITS" AS SALESFACT."UNITS",
  PRIVATE SALESFACT."REVENUE" AS SALESFACT."REVENUE",
  PRIVATE SENTIMENT."DATEID" AS SENTIMENT."DATEID",
  PRIVATE SENTIMENT."STATEID" AS SENTIMENT."STATEID",
  PRIVATE SENTIMENT."SCORE" AS SENTIMENT."SCORE",
  PRIVATE SENTIMENT."PRODUCTID" AS SENTIMENT."PRODUCTID"
)
DIMENSIONS (
  CATEGORY."CATEGORY" AS CATEGORY."CATEGORY" WITH SYNONYMS = ('Product Category'),
  CATEGORY."CHANNEL" AS CATEGORY."CHANNEL",
  CATEGORY."SORT" AS CATEGORY."SORT",
  COL_DATE."COL_DATE" AS COL_DATE."COL_DATE" WITH SYNONYMS = ('Date'),
  COL_DATE."MONTHNAME" AS COL_DATE."MONTHNAME",
  COL_DATE."MONTH" AS COL_DATE."MONTH",
  COL_DATE."QUARTER" AS COL_DATE."QUARTER",
  COL_DATE."RUNNING_MONTHS" AS COL_DATE."RUNNING_MONTHS" WITH SYNONYMS = ('Running Months'),
  COL_DATE."ROLLING_PERIOD" AS COL_DATE."ROLLING_PERIOD" WITH SYNONYMS = ('Rolling Period'),
  COL_DATE."MONTHS" AS COL_DATE."MONTHS",
  GEO."CITY" AS GEO."CITY",
  GEO."STATE" AS GEO."STATE",
  GEO."REGION" AS GEO."REGION" WITH SYNONYMS = ('Sales Region'),
  GEO."DISTRICT" AS GEO."DISTRICT",
  INDICATORS."STATUS" AS INDICATORS."STATUS",
  INDICATORS."IMAGE" AS INDICATORS."IMAGE",
  KPI."CATEGORY" AS KPI."CATEGORY",
  MANUFACTURER."MANUFACTURER" AS MANUFACTURER."MANUFACTURER",
  MANUFACTURER."MFGISVANARSDEL" AS MANUFACTURER."MFGISVANARSDEL",
  PRODUCT."MANUFACTURER" AS PRODUCT."MANUFACTURER",
  PRODUCT."CATEGORY" AS PRODUCT."CATEGORY",
  PRODUCT."SEGMENT" AS PRODUCT."SEGMENT",
  PRODUCT."PRODUCT" AS PRODUCT."PRODUCT",
  PRODUCT."ISVANARSDEL" AS PRODUCT."ISVANARSDEL" WITH SYNONYMS = ('Is Our Product'),
  PRODUCT."ISCOMPETE" AS PRODUCT."ISCOMPETE" WITH SYNONYMS = ('Is Competitor Product'),
  COL_DATE."MONTHNO" AS COL_DATE."MONTHNO",
  PRIVATE COL_DATE."MONTHID" AS COL_DATE."MONTHID",
  COL_DATE."YEAR" AS COL_DATE."YEAR",
  PRIVATE GEO."ZIP" AS GEO."ZIP",
  INDICATORS."SORT" AS INDICATORS."SORT",
  PRIVATE KPI."KPI" AS KPI."KPI",
  PRIVATE MANUFACTURER."MANUFACTURERID" AS MANUFACTURER."MANUFACTURERID",
  PRIVATE PRODUCT."PRODUCTID" AS PRODUCT."PRODUCTID",
  PRIVATE PRODUCT."ISCOMPETEHIDE" AS PRODUCT."ISCOMPETEHIDE",
  PRIVATE PRODUCT."MANUFACTURERID" AS PRODUCT."MANUFACTURERID",
  PRIVATE SALESFACT."PRODUCTID" AS SALESFACT."PRODUCTID",
  PRIVATE SALESFACT."COL_DATE" AS SALESFACT."COL_DATE" WITH SYNONYMS = ('Date'),
  PRIVATE SALESFACT."ZIP" AS SALESFACT."ZIP",
  PRIVATE SENTIMENT."MANUFACTURERID" AS SENTIMENT."MANUFACTURERID",
  PRIVATE SENTIMENT."MANUFACTURER" AS SENTIMENT."MANUFACTURER",
  PRIVATE SENTIMENT."COL_DATE" AS SENTIMENT."COL_DATE" WITH SYNONYMS = ('Date'),
  PRIVATE SENTIMENT."STATE" AS SENTIMENT."STATE",
  PRIVATE SENTIMENT."ZIP" AS SENTIMENT."ZIP"
)
METRICS (
  PRIVATE SALESFACT."KPI01" AS CAST(NULL AS DOUBLE) COMMENT = 'not applicable: expression''s root operation produces a string value, not a numeric aggregate — Snowflake semantic-view metrics must be aggregate expressions. This field should be modeled as a dimension attribute instead.',
  SALESFACT."KPI02" AS CAST(NULL AS DOUBLE) COMMENT = 'not applicable: expression''s root operation produces a string value, not a numeric aggregate — Snowflake semantic-view metrics must be aggregate expressions. This field should be modeled as a dimension attribute instead.',
  PRODUCT."COUNT_OF_PRODUCT" AS COUNT(PRODUCT.PRODUCT),
  PRODUCT."NEWCOUNT_OF_PRODUCT" AS CAST(NULL AS DOUBLE) COMMENT = 'DAX translation failed: declined: COUNTBLANK on a text or untyped column (empty-string handling) is not translated',
  PRODUCT."NEWNEWCOUNT_OF_PRODUCT" AS CAST(NULL AS DOUBLE) COMMENT = 'DAX translation failed: declined: COUNTBLANK on a text or untyped column (empty-string handling) is not translated',
  SALESFACT."TOTAL_UNITS" AS SUM(SALESFACT.UNITS::FLOAT) WITH SYNONYMS = ('Units Sold'),
  SALESFACT."SALES_DOL" AS SUM(SALESFACT.REVENUE::FLOAT) WITH SYNONYMS = ('Total Revenue'),
  SENTIMENT."SENTIMENT" AS AVG(SENTIMENT.SCORE) WITH SYNONYMS = ('Brand Sentiment Score'),
  SALESFACT."TOTAL_UNITS_YTD" AS SUM(CASE WHEN SALESFACT."COL_DATE" >= DATE_TRUNC('YEAR', CURRENT_DATE()) AND SALESFACT."COL_DATE" <= CURRENT_DATE() THEN SALESFACT.UNITS ELSE NULL END::FLOAT) COMMENT = 'Note: DAX CALCULATE filters override existing filters on that column, while the SUM(CASE WHEN ...::FLOAT) translation doesn''t, so results differ when grouping by the filtered column. Time-intelligence window is anchored to CURRENT_DATE() because no data-anchored period flag was available; DAX anchors to the last date in the filter context, so values differ when the data does not extend to today.',
  SALESFACT."TOTAL_VANARSDEL_UNITS_YTD" AS SUM(CASE WHEN PRODUCT.ISVANARSDEL = 'Yes' THEN CASE WHEN SALESFACT."COL_DATE" >= DATE_TRUNC('YEAR', CURRENT_DATE()) AND SALESFACT."COL_DATE" <= CURRENT_DATE() THEN SALESFACT.UNITS ELSE NULL END ELSE NULL END::FLOAT) COMMENT = 'Note: DAX CALCULATE filters override existing filters on that column, while the SUM(CASE WHEN ...::FLOAT) translation doesn''t, so results differ when grouping by the filtered column. Time-intelligence window is anchored to CURRENT_DATE() because no data-anchored period flag was available; DAX anchors to the last date in the filter context, so values differ when the data does not extend to today.',
  SALESFACT."TOTAL_OTHER_UNITS_YTD" AS SUM(CASE WHEN PRODUCT.ISVANARSDEL = 'No' THEN CASE WHEN SALESFACT."COL_DATE" >= DATE_TRUNC('YEAR', CURRENT_DATE()) AND SALESFACT."COL_DATE" <= CURRENT_DATE() THEN SALESFACT.UNITS ELSE NULL END ELSE NULL END::FLOAT) COMMENT = 'Note: DAX CALCULATE filters override existing filters on that column, while the SUM(CASE WHEN ...::FLOAT) translation doesn''t, so results differ when grouping by the filtered column. Time-intelligence window is anchored to CURRENT_DATE() because no data-anchored period flag was available; DAX anchors to the last date in the filter context, so values differ when the data does not extend to today.',
  SALESFACT."TOTAL_VANARSDEL_UNITS" AS SUM(CASE WHEN PRODUCT.ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END::FLOAT) WITH SYNONYMS = ('Our Brand Units') COMMENT = 'Note: DAX CALCULATE filters override existing filters on that column, while the SUM(CASE WHEN ...::FLOAT) translation doesn''t, so results differ when grouping by the filtered column.',
  SALESFACT."TOTAL_OTHER_UNITS" AS SUM(CASE WHEN PRODUCT.ISVANARSDEL = 'No' THEN SALESFACT.UNITS ELSE NULL END::FLOAT) WITH SYNONYMS = ('Competitor Units') COMMENT = 'Note: DAX CALCULATE filters override existing filters on that column, while the SUM(CASE WHEN ...::FLOAT) translation doesn''t, so results differ when grouping by the filtered column.',
  SALESFACT."PCT_UNITS_MARKET_SHARE" AS CASE WHEN COALESCE((SUM(CASE WHEN PRODUCT.ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END::FLOAT)), 0) = 0 THEN 0 ELSE IFF(COALESCE((SUM(SALESFACT.UNITS::FLOAT)), 0) = 0, 0, (SUM(CASE WHEN PRODUCT.ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END::FLOAT)) / (SUM(SALESFACT.UNITS::FLOAT))) END WITH SYNONYMS = ('Market Share %'),
  SALESFACT."TOTAL_CATEGORY_VOLUME" AS (SUM(SALESFACT.UNITS::FLOAT)) WITH SYNONYMS = ('Category Volume'),
  SALESFACT."TOTAL_COMPETE_VOLUME" AS SUM(CASE WHEN PRODUCT.ISVANARSDEL = 'No' THEN SALESFACT.UNITS END::FLOAT),
  SALESFACT."PCT_CATEGORY_COMPETE_SHARE" AS FLOOR((SUM(CASE WHEN PRODUCT.ISVANARSDEL = 'No' THEN SALESFACT.UNITS END::FLOAT)) / NULLIF((SUM(SALESFACT.UNITS::FLOAT)), 0) * 100),
  SALESFACT."TOTAL_UNITS_SPLY" AS SUM(CASE WHEN YEAR(SALESFACT."COL_DATE") = YEAR(DATEADD(YEAR, -1, CURRENT_DATE())) AND SALESFACT."COL_DATE" BETWEEN DATEADD(YEAR, -1, DATE_TRUNC('YEAR', CURRENT_DATE())) AND DATEADD(YEAR, -1, CURRENT_DATE()) THEN SALESFACT.UNITS ELSE NULL END::FLOAT) COMMENT = 'Note: DAX CALCULATE filters override existing filters on that column, while the SUM(CASE WHEN ...::FLOAT) translation doesn''t, so results differ when grouping by the filtered column. Time-intelligence window is anchored to CURRENT_DATE() because no data-anchored period flag was available; DAX anchors to the last date in the filter context, so values differ when the data does not extend to today.',
  SALESFACT."TOTAL_UNITS_YTD_SPLY" AS (SUM(CASE WHEN SALESFACT."COL_DATE" >= DATE_TRUNC('YEAR', DATEADD(YEAR, -1, CURRENT_DATE())) AND SALESFACT."COL_DATE" <= DATEADD(YEAR, -1, CURRENT_DATE()) THEN SALESFACT.UNITS ELSE NULL END::FLOAT)) COMMENT = 'Note: DAX CALCULATE filters override existing filters on that column, while the SUM(CASE WHEN ...::FLOAT) translation doesn''t, so results differ when grouping by the filtered column. Time-intelligence window is anchored to CURRENT_DATE() because no data-anchored period flag was available; DAX anchors to the last date in the filter context, so values differ when the data does not extend to today.',
  SALESFACT."TOTAL_VANARSDEL_UNITS_YTD_SPLY" AS (SUM(CASE WHEN PRODUCT.ISVANARSDEL = 'Yes' THEN CASE WHEN SALESFACT."COL_DATE" >= DATE_TRUNC('YEAR', DATEADD(YEAR, -1, CURRENT_DATE())) AND SALESFACT."COL_DATE" <= DATEADD(YEAR, -1, CURRENT_DATE()) THEN SALESFACT.UNITS ELSE NULL END ELSE NULL END::FLOAT)) COMMENT = 'Note: Time-intelligence window is anchored to CURRENT_DATE() because no data-anchored period flag was available; DAX anchors to the last date in the filter context, so values differ when the data does not extend to today. DAX CALCULATE filters override existing filters on that column, while the SUM(CASE WHEN ...::FLOAT) translation doesn''t, so results differ when grouping by the filtered column.',
  SALESFACT."TOTAL_OTHER_UNITS_YTD_SPLY" AS (SUM(CASE WHEN PRODUCT.ISVANARSDEL = 'No' THEN CASE WHEN SALESFACT."COL_DATE" >= DATE_TRUNC('YEAR', DATEADD(YEAR, -1, CURRENT_DATE())) AND SALESFACT."COL_DATE" <= DATEADD(YEAR, -1, CURRENT_DATE()) THEN SALESFACT.UNITS ELSE NULL END ELSE NULL END::FLOAT)) COMMENT = 'Note: Time-intelligence window is anchored to CURRENT_DATE() because no data-anchored period flag was available; DAX anchors to the last date in the filter context, so values differ when the data does not extend to today. DAX CALCULATE filters override existing filters on that column, while the SUM(CASE WHEN ...::FLOAT) translation doesn''t, so results differ when grouping by the filtered column.',
  SALESFACT."PCT_UNITS_MARKET_SHARE_YTD" AS (SUM(CASE WHEN PRODUCT.ISVANARSDEL = 'Yes' THEN CASE WHEN SALESFACT."COL_DATE" >= DATE_TRUNC('YEAR', CURRENT_DATE()) AND SALESFACT."COL_DATE" <= CURRENT_DATE() THEN SALESFACT.UNITS ELSE NULL END ELSE NULL END::FLOAT)) / NULLIF((SUM(CASE WHEN SALESFACT."COL_DATE" >= DATE_TRUNC('YEAR', CURRENT_DATE()) AND SALESFACT."COL_DATE" <= CURRENT_DATE() THEN SALESFACT.UNITS ELSE NULL END::FLOAT)), 0) COMMENT = 'Note: Time-intelligence window is anchored to CURRENT_DATE() because no data-anchored period flag was available; DAX anchors to the last date in the filter context, so values differ when the data does not extend to today.',
  SALESFACT."PCT_MARKET_SHARE_SPLY_YTD" AS ((SUM(CASE WHEN PRODUCT.ISVANARSDEL = 'Yes' THEN CASE WHEN SALESFACT."COL_DATE" >= DATE_TRUNC('YEAR', DATEADD(YEAR, -1, CURRENT_DATE())) AND SALESFACT."COL_DATE" <= DATEADD(YEAR, -1, CURRENT_DATE()) THEN SALESFACT.UNITS ELSE NULL END ELSE NULL END::FLOAT)) / NULLIF((SUM(CASE WHEN SALESFACT."COL_DATE" >= DATE_TRUNC('YEAR', DATEADD(YEAR, -1, CURRENT_DATE())) AND SALESFACT."COL_DATE" <= DATEADD(YEAR, -1, CURRENT_DATE()) THEN SALESFACT.UNITS ELSE NULL END::FLOAT)), 0)) COMMENT = 'Note: Time-intelligence window is anchored to CURRENT_DATE() because no data-anchored period flag was available; DAX anchors to the last date in the filter context, so values differ when the data does not extend to today. DAX CALCULATE filters override existing filters on that column, while the SUM(CASE WHEN ...::FLOAT) translation doesn''t, so results differ when grouping by the filtered column.',
  SALESFACT."PCT_UNIT_MARKET_SHARE_YOY_CHANGE" AS CASE WHEN (CASE WHEN COALESCE((SUM(CASE WHEN PRODUCT.ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END::FLOAT)), 0) = 0 THEN 0 ELSE IFF(COALESCE((SUM(SALESFACT.UNITS::FLOAT)), 0) = 0, 0, (SUM(CASE WHEN PRODUCT.ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END::FLOAT)) / (SUM(SALESFACT.UNITS::FLOAT))) END) IS NULL AND (CASE WHEN COALESCE((SUM(CASE WHEN YEAR(SALESFACT."COL_DATE") = YEAR(DATEADD(YEAR, -1, CURRENT_DATE())) AND SALESFACT."COL_DATE" BETWEEN DATEADD(YEAR, -1, DATE_TRUNC('YEAR', CURRENT_DATE())) AND DATEADD(YEAR, -1, CURRENT_DATE()) THEN CASE WHEN PRODUCT.ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END ELSE NULL END::FLOAT)), 0) = 0 THEN 0 ELSE IFF(COALESCE((SUM(CASE WHEN YEAR(SALESFACT."COL_DATE") = YEAR(DATEADD(YEAR, -1, CURRENT_DATE())) AND SALESFACT."COL_DATE" BETWEEN DATEADD(YEAR, -1, DATE_TRUNC('YEAR', CURRENT_DATE())) AND DATEADD(YEAR, -1, CURRENT_DATE()) THEN SALESFACT.UNITS ELSE NULL END::FLOAT)), 0) = 0, 0, (SUM(CASE WHEN YEAR(SALESFACT."COL_DATE") = YEAR(DATEADD(YEAR, -1, CURRENT_DATE())) AND SALESFACT."COL_DATE" BETWEEN DATEADD(YEAR, -1, DATE_TRUNC('YEAR', CURRENT_DATE())) AND DATEADD(YEAR, -1, CURRENT_DATE()) THEN CASE WHEN PRODUCT.ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END ELSE NULL END::FLOAT)) / (SUM(CASE WHEN YEAR(SALESFACT."COL_DATE") = YEAR(DATEADD(YEAR, -1, CURRENT_DATE())) AND SALESFACT."COL_DATE" BETWEEN DATEADD(YEAR, -1, DATE_TRUNC('YEAR', CURRENT_DATE())) AND DATEADD(YEAR, -1, CURRENT_DATE()) THEN SALESFACT.UNITS ELSE NULL END::FLOAT))) END) IS NULL THEN NULL ELSE COALESCE((CASE WHEN COALESCE((SUM(CASE WHEN PRODUCT.ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END::FLOAT)), 0) = 0 THEN 0 ELSE IFF(COALESCE((SUM(SALESFACT.UNITS::FLOAT)), 0) = 0, 0, (SUM(CASE WHEN PRODUCT.ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END::FLOAT)) / (SUM(SALESFACT.UNITS::FLOAT))) END), 0) - COALESCE((CASE WHEN COALESCE((SUM(CASE WHEN YEAR(SALESFACT."COL_DATE") = YEAR(DATEADD(YEAR, -1, CURRENT_DATE())) AND SALESFACT."COL_DATE" BETWEEN DATEADD(YEAR, -1, DATE_TRUNC('YEAR', CURRENT_DATE())) AND DATEADD(YEAR, -1, CURRENT_DATE()) THEN CASE WHEN PRODUCT.ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END ELSE NULL END::FLOAT)), 0) = 0 THEN 0 ELSE IFF(COALESCE((SUM(CASE WHEN YEAR(SALESFACT."COL_DATE") = YEAR(DATEADD(YEAR, -1, CURRENT_DATE())) AND SALESFACT."COL_DATE" BETWEEN DATEADD(YEAR, -1, DATE_TRUNC('YEAR', CURRENT_DATE())) AND DATEADD(YEAR, -1, CURRENT_DATE()) THEN SALESFACT.UNITS ELSE NULL END::FLOAT)), 0) = 0, 0, (SUM(CASE WHEN YEAR(SALESFACT."COL_DATE") = YEAR(DATEADD(YEAR, -1, CURRENT_DATE())) AND SALESFACT."COL_DATE" BETWEEN DATEADD(YEAR, -1, DATE_TRUNC('YEAR', CURRENT_DATE())) AND DATEADD(YEAR, -1, CURRENT_DATE()) THEN CASE WHEN PRODUCT.ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END ELSE NULL END::FLOAT)) / (SUM(CASE WHEN YEAR(SALESFACT."COL_DATE") = YEAR(DATEADD(YEAR, -1, CURRENT_DATE())) AND SALESFACT."COL_DATE" BETWEEN DATEADD(YEAR, -1, DATE_TRUNC('YEAR', CURRENT_DATE())) AND DATEADD(YEAR, -1, CURRENT_DATE()) THEN SALESFACT.UNITS ELSE NULL END::FLOAT))) END), 0) END COMMENT = 'Note: Time-intelligence window is anchored to CURRENT_DATE() because no data-anchored period flag was available; DAX anchors to the last date in the filter context, so values differ when the data does not extend to today.',
  SALESFACT."PCT_UNITS_MARKET_SHARE_SPLY" AS CASE WHEN COALESCE((SUM(CASE WHEN YEAR(SALESFACT."COL_DATE") = YEAR(DATEADD(YEAR, -1, CURRENT_DATE())) AND SALESFACT."COL_DATE" BETWEEN DATEADD(YEAR, -1, DATE_TRUNC('YEAR', CURRENT_DATE())) AND DATEADD(YEAR, -1, CURRENT_DATE()) THEN CASE WHEN PRODUCT.ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END ELSE NULL END::FLOAT)), 0) = 0 THEN 0 ELSE IFF(COALESCE((SUM(CASE WHEN YEAR(SALESFACT."COL_DATE") = YEAR(DATEADD(YEAR, -1, CURRENT_DATE())) AND SALESFACT."COL_DATE" BETWEEN DATEADD(YEAR, -1, DATE_TRUNC('YEAR', CURRENT_DATE())) AND DATEADD(YEAR, -1, CURRENT_DATE()) THEN SALESFACT.UNITS ELSE NULL END::FLOAT)), 0) = 0, 0, (SUM(CASE WHEN YEAR(SALESFACT."COL_DATE") = YEAR(DATEADD(YEAR, -1, CURRENT_DATE())) AND SALESFACT."COL_DATE" BETWEEN DATEADD(YEAR, -1, DATE_TRUNC('YEAR', CURRENT_DATE())) AND DATEADD(YEAR, -1, CURRENT_DATE()) THEN CASE WHEN PRODUCT.ISVANARSDEL = 'Yes' THEN SALESFACT.UNITS ELSE NULL END ELSE NULL END::FLOAT)) / (SUM(CASE WHEN YEAR(SALESFACT."COL_DATE") = YEAR(DATEADD(YEAR, -1, CURRENT_DATE())) AND SALESFACT."COL_DATE" BETWEEN DATEADD(YEAR, -1, DATE_TRUNC('YEAR', CURRENT_DATE())) AND DATEADD(YEAR, -1, CURRENT_DATE()) THEN SALESFACT.UNITS ELSE NULL END::FLOAT))) END COMMENT = 'Note: Time-intelligence window is anchored to CURRENT_DATE() because no data-anchored period flag was available; DAX anchors to the last date in the filter context, so values differ when the data does not extend to today. DAX CALCULATE filters override existing filters on that column, while the SUM(CASE WHEN ...::FLOAT) translation doesn''t, so results differ when grouping by the filtered column.',
  SALESFACT."TOTAL_UNITS_R12MS" AS SUM(CASE WHEN SALESFACT._CURRENT_FISCAL_PERIOD IS NOT NULL AND COL_DATE.MONTHINDEX <= SALESFACT._CURRENT_FISCAL_PERIOD AND COL_DATE.MONTHINDEX > SALESFACT._CURRENT_FISCAL_PERIOD - 12 THEN SALESFACT.UNITS::FLOAT END::FLOAT) COMMENT = 'Note: Time-intelligence window is anchored to CURRENT_DATE() because no data-anchored period flag was available; DAX anchors to the last date in the filter context, so values differ when the data does not extend to today. DAX CALCULATE filters override existing filters on that column, while the SUM(CASE WHEN ...::FLOAT) translation doesn''t, so results differ when grouping by the filtered column.',
  SALESFACT."TOTAL_VANARSDEL_UNITS_R12M" AS SUM(CASE WHEN PRODUCT.ISVANARSDEL = 'Yes' THEN CASE WHEN SALESFACT._CURRENT_FISCAL_PERIOD IS NOT NULL AND COL_DATE.MONTHINDEX <= SALESFACT._CURRENT_FISCAL_PERIOD AND COL_DATE.MONTHINDEX > SALESFACT._CURRENT_FISCAL_PERIOD - 12 THEN SALESFACT.UNITS::FLOAT END ELSE NULL END::FLOAT) COMMENT = 'Note: Time-intelligence window is anchored to CURRENT_DATE() because no data-anchored period flag was available; DAX anchors to the last date in the filter context, so values differ when the data does not extend to today. DAX CALCULATE filters override existing filters on that column, while the SUM(CASE WHEN ...::FLOAT) translation doesn''t, so results differ when grouping by the filtered column.',
  SALESFACT."TOTAL_OTHER_UNITS_R12M" AS SUM(CASE WHEN PRODUCT.ISVANARSDEL = 'No' THEN CASE WHEN SALESFACT._CURRENT_FISCAL_PERIOD IS NOT NULL AND COL_DATE.MONTHINDEX <= SALESFACT._CURRENT_FISCAL_PERIOD AND COL_DATE.MONTHINDEX > SALESFACT._CURRENT_FISCAL_PERIOD - 12 THEN SALESFACT.UNITS::FLOAT END ELSE NULL END::FLOAT) COMMENT = 'Note: Time-intelligence window is anchored to CURRENT_DATE() because no data-anchored period flag was available; DAX anchors to the last date in the filter context, so values differ when the data does not extend to today. DAX CALCULATE filters override existing filters on that column, while the SUM(CASE WHEN ...::FLOAT) translation doesn''t, so results differ when grouping by the filtered column.',
  SALESFACT."PCT_UNITS_MARKET_SHARE_R12M" AS CASE WHEN COALESCE((SUM(CASE WHEN PRODUCT.ISVANARSDEL = 'Yes' THEN CASE WHEN SALESFACT._CURRENT_FISCAL_PERIOD IS NOT NULL AND COL_DATE.MONTHINDEX <= SALESFACT._CURRENT_FISCAL_PERIOD AND COL_DATE.MONTHINDEX > SALESFACT._CURRENT_FISCAL_PERIOD - 12 THEN SALESFACT.UNITS::FLOAT END ELSE NULL END::FLOAT)), 0) = 0 THEN 0 ELSE IFF(COALESCE((SUM(CASE WHEN SALESFACT._CURRENT_FISCAL_PERIOD IS NOT NULL AND COL_DATE.MONTHINDEX <= SALESFACT._CURRENT_FISCAL_PERIOD AND COL_DATE.MONTHINDEX > SALESFACT._CURRENT_FISCAL_PERIOD - 12 THEN SALESFACT.UNITS::FLOAT END::FLOAT)), 0) = 0, 0, (SUM(CASE WHEN PRODUCT.ISVANARSDEL = 'Yes' THEN CASE WHEN SALESFACT._CURRENT_FISCAL_PERIOD IS NOT NULL AND COL_DATE.MONTHINDEX <= SALESFACT._CURRENT_FISCAL_PERIOD AND COL_DATE.MONTHINDEX > SALESFACT._CURRENT_FISCAL_PERIOD - 12 THEN SALESFACT.UNITS::FLOAT END ELSE NULL END::FLOAT)) / (SUM(CASE WHEN SALESFACT._CURRENT_FISCAL_PERIOD IS NOT NULL AND COL_DATE.MONTHINDEX <= SALESFACT._CURRENT_FISCAL_PERIOD AND COL_DATE.MONTHINDEX > SALESFACT._CURRENT_FISCAL_PERIOD - 12 THEN SALESFACT.UNITS::FLOAT END::FLOAT))) END COMMENT = 'Note: Time-intelligence window is anchored to CURRENT_DATE() because no data-anchored period flag was available; DAX anchors to the last date in the filter context, so values differ when the data does not extend to today.',
